        if (pct.signum() <= 0 || pct.compareTo(HUNDRED) > 0) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
                    "A share is more than 0.00 and at most 100.00.");
        }
        return pct;
    }
